alter table public.customer_debt_ledger enable row level security;
drop policy if exists customer_debt_select on public.customer_debt_ledger; create policy customer_debt_select on public.customer_debt_ledger for select to authenticated using(company_id=public.get_my_company_id());
drop policy if exists customer_debt_insert on public.customer_debt_ledger; create policy customer_debt_insert on public.customer_debt_ledger for insert to authenticated with check(false);
drop policy if exists customer_debt_update on public.customer_debt_ledger; create policy customer_debt_update on public.customer_debt_ledger for update to authenticated using(false);
drop policy if exists customer_debt_delete on public.customer_debt_ledger; create policy customer_debt_delete on public.customer_debt_ledger for delete to authenticated using(false);
create index if not exists idx_customer_debt_company_customer on public.customer_debt_ledger(company_id,customer_id,created_at desc);
create or replace function public.record_customer_debt(p_customer_id uuid,p_source_type text,p_source_id uuid default null,p_debit numeric default 0,p_credit numeric default 0,p_invoice_id uuid default null,p_branch_id uuid default null,p_notes text default null) returns uuid language plpgsql security definer set search_path='public' as $$ declare v_company uuid; v_id uuid; begin if auth.uid() is null then raise exception 'Not authenticated'; end if; if not public.has_permission('payments.manage') then raise exception 'Permission denied'; end if; v_company:=public.get_my_company_id(); if v_company is null then raise exception 'Company not found'; end if; if not exists(select 1 from customers where id=p_customer_id and company_id=v_company) then raise exception 'Customer not found'; end if; if p_debit<0 or p_credit<0 or(p_debit>0 and p_credit>0) then raise exception 'Invalid debit/credit'; end if; if p_debit=0 and p_credit=0 then raise exception 'A ledger entry must have a value'; end if; insert into customer_debt_ledger(company_id,customer_id,invoice_id,source_type,source_id,debit,credit,branch_id,notes,created_by) values(v_company,p_customer_id,p_invoice_id,p_source_type,p_source_id,p_debit,p_credit,p_branch_id,p_notes,auth.uid()) returning id into v_id; return v_id; end; $$;
grant execute on function public.record_customer_debt(uuid,text,uuid,numeric,numeric,uuid,uuid,text) to authenticated; revoke execute on function public.record_customer_debt(uuid,text,uuid,numeric,numeric,uuid,uuid,text) from anon;
revoke execute on function public.get_customer_balances() from anon; grant execute on function public.get_customer_balances() to authenticated;
